"""逃生舱写法：业务核心与框架解耦，框架只当「编排壳」。

领域函数（retrieve / need_human / compose）不 import 任何 Agent 框架，
所以同一套业务逻辑既能被「零框架的三行 while」驱动，
也能被 LangGraph 驱动。换框架时只重写最外层的壳。
"""
from dataclasses import dataclass


@dataclass
class TicketState:
    question: str
    docs: tuple = ()
    need_human_review: bool = False
    answer: str = ""


class InMemoryRetriever:
    """检索端口的测试实现；生产换成向量库时领域层完全无感。"""

    def __init__(self, corpus):
        self._corpus = tuple(corpus)

    def search(self, question, top_k=3):
        hits = [doc for doc in self._corpus if any(ch in doc for ch in question)]
        return tuple(hits[:top_k])


# ---------- 领域层：纯函数，可单测，不依赖框架 ----------
def retrieve(question, retriever):
    return retriever.search(question)


def need_human(docs, min_hits=1):
    """命中不足就转人工——这是业务规则，不该被埋进框架节点里。"""
    return len(docs) < min_hits


def compose(docs, human):
    if human:
        return "未命中知识库，已转人工客服"
    return "根据资料：" + " / ".join(docs)


# ---------- 壳 A：零框架，spike 阶段先用它验证业务是否成立 ----------
def run_plain(question, retriever):
    docs = retrieve(question, retriever)
    human = need_human(docs)
    return compose(docs, human)


# ---------- 壳 B：换 LangGraph，只加三行适配，领域函数原样复用 ----------
def build_langgraph_app(retriever):
    from langgraph.graph import StateGraph, START, END

    graph = StateGraph(TicketState)
    graph.add_node("retrieve", lambda s: {"docs": retrieve(s.question, retriever)})
    graph.add_node("triage", lambda s: {"need_human_review": need_human(s.docs)})
    graph.add_node("compose", lambda s: {"answer": compose(s.docs, s.need_human_review)})
    graph.add_edge(START, "retrieve")
    graph.add_edge("retrieve", "triage")
    graph.add_edge("triage", "compose")
    graph.add_edge("compose", END)
    return graph.compile()


if __name__ == "__main__":
    kb = ["退款政策：7 天无理由退货", "发票开具流程说明"]
    bot = InMemoryRetriever(kb)
    print(run_plain("退款", bot))
    print(run_plain("改地址", bot))

from typing import TypedDict
from langgraph.graph import StateGraph, END

class State(TypedDict):
    question: str
    draft: str
    steps: int

def think(state: State) -> State:
    return {"draft": "分析「" + state["question"] + "」的结论", "steps": state["steps"] + 1}

def decide(state: State) -> str:
    return END if state["steps"] >= 2 else "think"

def build():
    g = StateGraph(State)
    g.add_node("think", think)
    g.add_edge("think", "decide")
    g.add_conditional_edges("decide", decide)
    g.set_entry_point("think")
    return g.compile()

if __name__ == "__main__":
    app = build()
    print(app.invoke({"question": "如何设计 Agent 记忆？", "draft": "", "steps": 0}))

from agents import Agent, Runner, function_tool

@function_tool
def get_weather(city: str) -> str:
    """查询城市天气"""
    return f"{city} 今天晴，25°C"

@function_tool
def calc_discount(price: float, rate: float) -> float:
    """按折扣率计算折后价"""
    return round(price * (1 - rate), 2)

assistant = Agent(
    name="智能助手",
    instructions="根据用户问题调用天气或折扣工具。",
    tools=[get_weather, calc_discount],
)

result = Runner.run_sync(assistant, "北京天气怎么样？再算下 200 元打 8 折")
print(result.final_output)

from llama_index.core import VectorStoreIndex, SimpleDirectoryReader, Settings
from llama_index.llms.openai import OpenAI

Settings.llm = OpenAI(model="gpt-4o-mini")

def build_qa(data_dir: str):
