"""Resources 与 Prompts 示例 Server：只读上下文 + 可复用提示模板。

Tools 是「让模型做事」，Resources 是「给模型看东西」，Prompts 是「教用户怎么问」。
三者都由同一个 FastMCP 实例注册，共用一条连接。
"""

import json

from mcp.server.fastmcp import FastMCP
from mcp.server.fastmcp.prompts import base

mcp = FastMCP("doc-context")

_RUNBOOKS = {
    "order": "订单服务值班手册：1) 看 QPS 大盘 2) 查 MySQL 慢查询 3) 必要时降级优惠券",
    "search": "搜索服务值班手册：1) 看 ES 集群状态 2) 检查索引延迟 3) 切读备集群",
}


# 第1步：固定 URI 的资源。资源是「只读上下文」，语义上等价于 HTTP GET，
# 不应产生副作用；是否读取由宿主/用户决定，而不是模型自己乱调。
@mcp.resource("config://service/limits")
def service_limits() -> str:
    """服务限流配置（只读）。"""
    return json.dumps(
        {"qps_limit": 3000, "burst": 500, "timeout_ms": 800},
        ensure_ascii=False,
    )


# 第2步：URI 模板资源。花括号里的占位符会成为函数参数，
# 客户端读取 doc://runbook/order 时，service 就是 "order"。
@mcp.resource("doc://runbook/{service}")
def runbook(service: str) -> str:
    """按服务名返回值班手册。"""
    return _RUNBOOKS.get(service, f"暂无 {service} 的值班手册")


# 第3步：Prompt 模板。返回纯字符串时会被包装成一条 user 消息，
# 宿主通常把它渲染成斜杠命令 / 快捷入口，由用户主动触发。
@mcp.prompt()
def incident_review(service: str, severity: str = "P2") -> str:
    """生成故障复盘提纲。"""
    return (
        f"请为 {service} 服务的 {severity} 级故障写复盘，包含：\n"
        "1. 时间线（发现/定位/止损/恢复）\n"
        "2. 根因分析（5 Why）\n"
        "3. 改进项（负责人 + 截止时间）"
    )


# 第4步：多轮 Prompt。返回 base.Message 列表可以预置对话上下文，
# 常用来做 few-shot 或给模型设定固定的回答格式。
@mcp.prompt()
def doc_qa(question: str) -> list[base.Message]:
    """文档问答模板：强制模型先引用出处再回答。"""
    return [
        base.AssistantMessage("我会先列出引用的文档标题，再给出答案。"),
        base.UserMessage(f"基于内部文档回答：{question}"),
    ]


if __name__ == "__main__":
    mcp.run(transport="stdio")

