import time
import functools

def trace(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        start = time.time()
        out = fn(*args, **kwargs)
        cost = round((time.time() - start) * 1000, 2)
        print("[trace] " + fn.__name__ + " 耗时 " + str(cost) + "ms")
        return out
    return wrapper

@trace
def ask(question: str) -> str:
    # 真实场景在此调用 LLM
    return "关于「" + question + "」的回答"

if __name__ == "__main__":
    print(ask("年假几天？"))

from langfuse import Langfuse
from langfuse import observe

# 生产可观测：在 Langfuse 追踪基础上叠加告警规则，问题定位从小时级→分钟级
langfuse = Langfuse()

# 第1步：定义告警阈值（响应时间 / 成本）
THRESHOLDS = {"latency_s": 10, "cost_usd": 0.05}

# 第2步：用 observe 包裹关键节点，自动采集每一步耗时与成本
@observe()
def agent_step(prompt: str) -> str:
    # 真实 Agent 调用；此处为示意
    return f"回答: {prompt[:10]}..."

# 第3步：拉取近期 trace，按阈值触发告警
def check_alerts():
    traces = langfuse.fetch_traces(limit=100).data
    for t in traces:
        lat = t.latency or 0
        if lat > THRESHOLDS["latency_s"]:
            print(f"🚨 告警 响应慢: {lat:.1f}s > {THRESHOLDS['latency_s']}s")
        cost = getattr(t, "total_cost", 0) or 0
        if cost > THRESHOLDS["cost_usd"]:
            print(f"🚨 告警 成本高: {cost:.4f} USD > {THRESHOLDS['cost_usd']}")

agent_step("演示一次埋点")
check_alerts()

import subprocess

def run_sandboxed(code: str, timeout_s: int = 5) -> str:
    try:
        res = subprocess.run(
            ["python", "-c", code],
            capture_output=True, text=True, timeout=timeout_s,
        )
        return res.stdout or res.stderr
    except subprocess.TimeoutExpired:
        return "执行超时，已终止"

if __name__ == "__main__":
    print(run_sandboxed("print(1 + 2)"))

import ast

from typing import Any


class SandboxError(Exception):
    pass


def check_comprehension(tree: ast.AST) -> None:
    """练习： 在这里实现三条规则。"""
    depth = 0
    for node in ast.walk(tree):
        if isinstance(node, ast.ListComp):
            depth += 1
        # 练习 1： 迭代源只能是变量名或 range(常量)，且常量 <= MAX_RANGE
        # 练习 2： depth > 1 时拒绝嵌套推导式
        # 练习 3： 推导式内部出现 ast.Attribute 时拒绝
    if depth > 1:
        raise SandboxError("禁止嵌套推导式")


def safe_eval_v2(expr: str, variables: dict) -> Any:
    tree = ast.parse(expr, mode="eval")
    check_comprehension(tree)
    env: dict[str, Any] = {"__builtins__": {}, "range": range}
    env.update(variables)
    return eval(compile(tree, "<safe>", "eval"), env)


if __name__ == "__main__":
    should_pass = [
        ("[x * 2 for x in nums]", {"nums": [1, 2, 3]}),
        ("[x for x in range(10) if x > 5]", {}),
    ]
    should_block = [
        ("[[y for y in x] for x in nums]", {"nums": [[1], [2]]}),
        ("[x.__class__ for x in nums]", {"nums": [1]}),
        ("[x for x in range(10 ** 9)]", {}),
    ]
    for expr, ctx in should_pass + should_block:
        try:
            print("PASS ", expr, "->", safe_eval_v2(expr, ctx))
        except Exception as err:
            print("BLOCK", expr, "->", err)
